const bytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0)).buffer;
export const anatomyIndices=new Uint16Array(bytes(''));
export const anatomyPoses=[
Float32Array.from(new Int16Array(bytes('')),v=>v/50000),
Float32Array.from(new Int16Array(bytes('')),v=>v/50000)
];
